import { invoke, listen, type InvokeOptions } from "@lantharos/sabine";

export const commands = {
	appState: (options?: InvokeOptions) => invoke<AppState>("app_state", {}, options),
	openLink: (params: {
		uri: string,
		token?: string | null,
	}, options?: InvokeOptions) => invoke<null>("open_link", params, options),
	ptyAck: (params: {
		id: number,
	}, options?: InvokeOptions) => invoke<null>("pty_ack", params, options),
	ptyAttach: (params: {
		id: number,
	}, options?: InvokeOptions) => invoke<null>("pty_attach", params, options),
	ptyClose: (params: {
		id: number,
	}, options?: InvokeOptions) => invoke<null>("pty_close", params, options),
	ptyForeground: (params: {
		id: number,
	}, options?: InvokeOptions) => invoke<string | null>("pty_foreground", params, options),
	ptyResize: (params: ({
		id: number,
	}) & (TerminalSize), options?: InvokeOptions) => invoke<null>("pty_resize", params, options),
	ptySpawn: (params: ({
		directory?: string | null,
		command?: string[] | null,
	}) & (TerminalSize), options?: InvokeOptions) => invoke<number>("pty_spawn", params, options),
	ptyWrite: (params: {
		id: number,
		data: string,
	}, options?: InvokeOptions) => invoke<null>("pty_write", params, options),
	resolveLaunch: (params: {
		arguments: string[],
		workingDirectory?: string | null,
	}, options?: InvokeOptions) => invoke<LaunchRequest>("resolve_launch", params, options),
	updateSettings: (params: {
		settings: Settings,
	}, options?: InvokeOptions) => invoke<null>("update_settings", params, options),
};

export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	kestrelPalette: (callback: (payload: import("@luft/ui").Palette) => void) => listen<import("@luft/ui").Palette>("kestrel.palette", callback),
	ternExited: (callback: (payload: TerminalExited) => void) => listen<TerminalExited>("tern.exited", callback),
	ternOutput: (callback: (payload: TerminalOutput) => void) => listen<TerminalOutput>("tern.output", callback),
};

export type AppState = {
	settings: Settings,
	launch: LaunchRequest,
	defaultShell: string,
	shells: string[],
	glass: boolean,
} & Appearance;

export type Appearance = {
	palette: import("@luft/ui").Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	locale: Locale,
};

export type Corners = "rounded" | "square";

export type CursorStyle = "block" | "bar" | "underline";

export type LaunchRequest = {
	directory: string | null,
	command: string[] | null,
};

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Motion = "full" | "reduced" | "off";

export type SchemePreference = "system" | "dark" | "light";

export type Settings = {
	fontSize: number,
	scrollback: number,
	cursorStyle: CursorStyle,
	cursorBlink: boolean,
	translucent: boolean,
	opacity: number,
	scheme: SchemePreference,
	shell: string | null,
	copyOnSelect: boolean,
	clipboardReads: boolean,
};

export type TerminalExited = {
	id: number,
	code: number,
};

export type TerminalOutput = {
	id: number,
	data: string,
};

export type TerminalSize = {
	cols: number,
	rows: number,
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};
